using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using Newtonsoft.Json;
public static class B2Record {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");string h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B2_Cooling/"));var root=s.GetRootGameObjects().Single(g=>g.name=="B2_C02_CoolingSector").transform;var rows=root.GetComponentsInChildren<Transform>(true).Select(t=>new{path=AnimationUtility.CalculateTransformPath(t,root),asset=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject),position=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},rotation=new[]{t.localEulerAngles.x,t.localEulerAngles.y,t.localEulerAngles.z},scale=new[]{t.localScale.x,t.localScale.y,t.localScale.z},active=t.gameObject.activeSelf}).ToArray();File.WriteAllText(h+"final_layout.json",JsonConvert.SerializeObject(rows,Formatting.Indented));var result=new{scene=s.path,saved=!s.isDirty,Application.isPlaying,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled,Application.runInBackground,objects=rows.Length};File.WriteAllText(h+"final_state.json",JsonConvert.SerializeObject(result,Formatting.Indented));Selection.activeGameObject=root.gameObject;SceneView.lastActiveSceneView?.LookAt(root.position+new Vector3(0,3,0),Quaternion.Euler(12,0,0),11);return result;}
}
